const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='kitchen-stock-v1',yen=n=>'¥'+Math.round(n).toLocaleString('ja-JP');
const CATEGORIES=[...new Set(ORDER_CATALOG.map(i=>i.category))];
let db={items:[],orders:[],history:[]},page='inventory',filter='すべて',search='';
let storageBlocked=false;
try {
  const saved=JSON.parse(localStorage.getItem(KEY));
  if(saved){
    if(!Array.isArray(saved.items)||!Array.isArray(saved.orders)||!Array.isArray(saved.history)) throw new Error('Invalid saved data');
    db=saved;
  }
  if(db.catalogVersion!==1){
    const backup=localStorage.getItem(KEY);
    if(backup) localStorage.setItem(KEY+'-before-catalog',backup);
    db.items.forEach(i=>{if(/^i[0-9]$/.test(i.id))i.archived=true});
    for(const item of ORDER_CATALOG) if(!db.items.some(i=>i.id===item.id)) db.items.push({...item});
    db.catalogVersion=1;
    localStorage.setItem(KEY,JSON.stringify(db));
  }
} catch(e) {
  storageBlocked=true;
  alert('保存データを読み込み・移行できませんでした。元のデータは上書きせず、閲覧専用で表示します。バックアップとブラウザの保存設定を確認してください。');
  if(!db.items.length) db.items=ORDER_CATALOG.map(i=>({...i}));
}
const activeItems=()=>db.items.filter(i=>!i.archived);
const needsOrder=i=>i.stock!==null&&i.min!==null&&(i.catalogItem?i.stock<i.min:i.stock<=i.min);
const targetQty=i=>i.catalogItem?i.min:i.min*2;
// 原票の適正数は発注点ではなく、補充後に維持する数量。
db.items.forEach(i=>{if(i.id.startsWith('catalog-'))i.catalogItem=true});
const stockText=i=>i.stock===null?'未入力':i.stock;
const priceText=p=>p===null?'単価未設定':yen(p);
const orderTotal=o=>o.lines.some(l=>l.price===null)?'金額未確定（単価未設定）':yen(o.lines.reduce((n,l)=>n+l.qty*l.price,0));
function persist(){if(storageBlocked)return false;try{localStorage.setItem(KEY,JSON.stringify(db));if(window.KitchenCloud?.enabled)window.KitchenCloud.save(db).catch(e=>toast('共有保存に失敗しました：'+e.message));return true}catch(e){alert('保存に失敗しました。ブラウザの保存容量・設定を確認し、バックアップしてください。');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').style.opacity=1;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.opacity=0,2800)}
const low=()=>activeItems().filter(needsOrder), pending=()=>db.orders.filter(o=>o.status==='発注済み');
const status=i=>i.stock===null?'<span class="pill">○ 在庫未入力</span>':i.stock===0?'<span class="pill out">● 在庫なし</span>':needsOrder(i)?'<span class="pill low">● 発注が必要</span>':i.min===null?'<span class="pill">適正数未設定</span>':'<span class="pill">● 適正在庫</span>';
function render(){const names={inventory:'在庫管理',orders:'発注管理',history:'入出庫履歴',suppliers:'仕入先'};$('#title').textContent=$('#breadcrumb').textContent=names[page];$('#subtitle').textContent={inventory:'商品のいまを把握して、仕込みにゆとりを。',orders:'必要な商品を、必要な分だけ。発注から入荷まで。',history:'商品の動きを、ひとつずつ記録。',suppliers:'いつもの仕入先と、商品をひと目で。'}[page];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#orderBadge').textContent=pending().length||'';$('#add').textContent=page==='orders'?'＋ 発注を作成':'＋ 商品を登録';$('#stats').innerHTML=[['登録商品',activeItems().length,'品目','すべての管理対象商品','▦'],['発注が必要',low().length,'品目','適正数未満の品目','↘'],['入荷待ち',pending().length,'件','発注済み・未入荷の発注','▤'],['在庫金額',activeItems().some(i=>i.stock===null||i.price===null)?'未確定':yen(activeItems().reduce((n,i)=>n+i.stock*i.price,0)),'','登録単価による概算','¥']].map((a,i)=>`<div class="stat ${i===1?'warn':''}"><label>${a[0]}</label><span class="symbol">${a[4]}</span><strong>${a[1]}<small>${a[2]}</small></strong><p>${a[3]}</p></div>`).join('');$('#alert').innerHTML=low().length?`<div class="notice"><span>◷</span><div><b>${low().length}品目が補充の目安を下回っています</b><small>在庫を確認して、次の営業に備えましょう。</small></div><button id="suggest">まとめて発注を作成 →</button></div>`:'';$('#suggest')?.addEventListener('click',()=>orderModal(true));$('#toolbar').innerHTML=page==='inventory'?`<div class="filters"><h2>商品一覧 <span style="color:#a0a998;font-size:12px">${activeItems().length}</span></h2><input id="search" placeholder="⌕ 商品名・仕入先で検索" aria-label="商品を検索" value="${esc(search)}"></div><div class="tabs">${['すべて','要発注','未入力',...new Set([...CATEGORIES,...activeItems().map(i=>i.category)]),'旧登録項目'].map(t=>`<button class="${filter===t?'selected':''}" data-filter="${t}">${t}</button>`).join('')}</div>`:`<div class="filters"><h2>${names[page]}一覧</h2><span style="font-size:11px;color:#87937f">${page==='orders'?'CSVをダウンロードして仕入先に送付できます':''}</span></div>`;$('#search')?.addEventListener('input',e=>{search=e.target.value;renderRows()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});renderRows()}
function renderRows(){let html='';if(page==='inventory'){const items=db.items.filter(i=>(filter==='旧登録項目'?i.archived:!i.archived&&(filter==='すべて'||filter==='要発注'&&needsOrder(i)||filter==='未入力'&&i.stock===null||filter===i.category))&&(i.name+i.supplier+(i.notes||'')).includes(search));html=`<table><thead><tr><th>商品名</th><th>カテゴリー</th><th>現在庫</th><th>適正数 / 発注点</th><th>ステータス</th><th>仕入先</th><th></th></tr></thead><tbody>${items.map(i=>`<tr><td><div class="food"><span class="foodicon">${i.icon||'◈'}</span><div><b>${esc(i.name)}</b><small>${priceText(i.price)} / ${esc(i.unit)}${i.notes?`<br><span class="review-note">要確認：${esc(i.notes)}</span>`:''}</small></div></div></td><td>${esc(i.category)}</td><td><span class="num">${stockText(i)}</span> <span style="color:#8e9886;font-size:10px">${esc(i.unit)}</span><div class="bar"><i style="width:${Math.min(100,i.stock/Math.max(1,i.min*3)*100)}%;${needsOrder(i)?'background:#d5ac65':''}"></i></div></td><td>${i.min??'未設定'} <small style="display:inline">${esc(i.unit)}</small></td><td>${status(i)}</td><td>${esc(i.supplier)}</td><td><button class="subtle" data-move="${i.id}">入出庫</button> <button class="subtle" data-edit="${i.id}" aria-label="${esc(i.name)}を編集">編集</button></td></tr>`).join('')}</tbody></table>${items.length?'':'<div class="empty">該当する商品はありません。</div>'}<div class="tablefoot">${items.length} 品目を表示　・　適正数未満で補充を提案します。旧登録項目は従来の発注点を適用します</div>`}else if(page==='orders'){html=db.orders.slice().reverse().map(o=>`<div class="order"><div><h3>${esc(o.supplier)}　<span class="pill">${o.status}</span></h3><small>${o.date} · ${o.id.slice(0,8)}</small><p>${o.lines.map(l=>`${esc(l.name)} × ${l.qty} ${esc(l.unit)}`).join(' / ')}</p><b>${orderTotal(o)}</b></div><div class="actions"><button data-csv="${o.id}">CSV出力</button>${o.status==='発注済み'?`<button class="primary" data-receive="${o.id}">入荷を記録</button>`:''}</div></div>`).join('')||'<div class="empty">まだ発注はありません。「発注を作成」から追加できます。</div>'}else if(page==='history'){html='<table><thead><tr><th>日時</th><th>商品</th><th>操作</th><th>数量</th><th>メモ</th></tr></thead><tbody>'+db.history.slice().reverse().map(h=>`<tr><td>${esc(h.date)}</td><td>${esc(h.name)}</td><td>${esc(h.type)}</td><td>${h.qty>0?'+':''}${h.qty===null?'初回設定':h.qty} ${esc(h.unit)}</td><td>${esc(h.note)}</td></tr>`).join('')+'</tbody></table>';if(!db.history.length)html='<div class="empty">入出庫や入荷を記録すると、ここに履歴が表示されます。</div>'}else{html=[...new Set(activeItems().map(i=>i.supplier))].map(s=>`<div class="order"><div><h3>⌂　${esc(s)}</h3><p>${activeItems().filter(i=>i.supplier===s).map(i=>esc(i.name)).join(' ・ ')}</p></div><span class="pill">${activeItems().filter(i=>i.supplier===s).length} 品目</span></div>`).join('')}$('#content').innerHTML=html;document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>itemModal(b.dataset.edit));document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>moveModal(b.dataset.move));document.querySelectorAll('[data-receive]').forEach(b=>b.onclick=()=>receive(b.dataset.receive));document.querySelectorAll('[data-csv]').forEach(b=>b.onclick=()=>{const o=db.orders.find(o=>o.id===b.dataset.csv);csv(['発注日','仕入先','商品','数量','単位','単価','金額'],o.lines.map(l=>[o.date,o.supplier,l.name,l.qty,l.unit,l.price??'',l.price===null?'':l.qty*l.price]),'発注書')})}
function modal(title,fields,submit){if(storageBlocked){toast('保存設定の問題を解消するまで編集できません');return}$('#modalTitle').textContent=title;$('#fields').innerHTML=fields;$('#form').onsubmit=e=>{e.preventDefault();if(submit(new FormData(e.target))!==false){$('#dialog').close();persist();render()}};$('#dialog').showModal()}
const input=(label,name,value='',type='text',required=true)=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value??'')}" ${required?'required':''} ${type==='number'?'min="0" max="100000000" step="0.01"':''} ${type==='text'?'maxlength="100"':''}></label>`;
function itemModal(id){const i=db.items.find(i=>i.id===id);modal(i?'商品を編集':'商品を登録',input('商品名','name',i?.name||'')+`<label>カテゴリー<select name="category">${[...new Set([...CATEGORIES,'その他',...(i?[i.category]:[])])].map(c=>`<option ${i?.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label>`+(i?'':input('初期在庫（空欄は未入力）','stock','','number',false))+input(i?.catalogItem?'適正数（補充目標）':'発注点','min',i?.min??'','number',false)+input('単位（kg・本・個 など）','unit',i?.unit||'kg')+input('単価（円・税抜／空欄は未設定）','price',i?.price??'','number',false)+input('仕入先名','supplier',i?.supplier||'')+input('確認メモ（任意）','notes',i?.notes||'','text',false),f=>{for(const k of ['name','unit','supplier'])if(!f.get(k).trim()){toast('空白だけの値は登録できません');return false}const v=Object.fromEntries(f);for(const k of ['stock','min','price'])if(k in v)v[k]=v[k]===''?null:Number(v[k]);if(i)Object.assign(i,v);else db.items.push({...v,id:crypto.randomUUID(),icon:'◈'});toast('商品を保存しました')})}
function log(i,type,qty,note){db.history.push({date:new Date().toLocaleString('ja-JP'),name:i.name,unit:i.unit,type,qty,note})}
function moveModal(id){const i=db.items.find(i=>i.id===id);modal(i.name+' の入出庫',`<p>現在庫：<b>${stockText(i)} ${esc(i.unit)}</b></p><label>操作<select name="type"><option ${i.stock===null?'disabled':''}>出庫（使用）</option><option ${i.stock===null?'disabled':''}>入庫</option><option ${i.stock===null?'disabled':''}>廃棄</option><option ${i.stock===null?'selected':''}>棚卸（実数に修正）</option></select></label>`+input('数量（'+i.unit+'）','qty','','number')+'<label>メモ<input name="note" maxlength="200" placeholder="仕込み・納品・棚卸など"></label>',f=>{const q=Number(f.get('qty')),t=f.get('type');if(i.stock===null&&!t.startsWith('棚卸')){toast('先に棚卸で現在庫を入力してください');return false}const next=t.startsWith('棚卸')?q:t==='入庫'?i.stock+q:i.stock-q;if(next<0){toast('現在庫を超える数量は出庫できません');return false}const wasUnknown=i.stock===null;const delta=wasUnknown?null:Math.round((next-i.stock)*100)/100;i.stock=Math.round(next*100)/100;log(i,t,delta,(wasUnknown?'初回棚卸：'+next+' '+i.unit+'。 ':'')+f.get('note'));toast('在庫を更新しました')})}
function orderModal(auto=false){const candidates=auto?low():activeItems();if(!candidates.length){toast('発注できる商品がありません');return}modal(auto?'不足商品から発注を作成':'発注を作成',`<p>仕入先ごとに発注を作成します。数量を0にした商品は含めません。作成後、CSVを仕入先へ送付してください。</p>`+candidates.map(i=>input(i.name+'（'+i.unit+'）',i.id,auto?Math.max(0,targetQty(i)-i.stock-pending().flatMap(o=>o.lines).filter(l=>l.id===i.id).reduce((s,l)=>s+l.qty,0)):0,'number')).join(''),f=>{const groups=Object.create(null);for(const i of candidates){const qty=Number(f.get(i.id));if(qty>0)(groups[i.supplier]??=[]).push({id:i.id,name:i.name,unit:i.unit,price:i.price,qty})}if(!Object.keys(groups).length){toast('1品目以上の数量を入力してください');return false}Object.entries(groups).forEach(([supplier,lines])=>db.orders.push({id:crypto.randomUUID(),date:new Date().toLocaleDateString('ja-JP'),supplier,lines,status:'発注済み'}));page='orders';toast('発注を作成しました。CSVを仕入先に送付してください')})}
function receive(id){const o=db.orders.find(o=>o.id===id);if(o.status!=='発注済み')return;const unknown=o.lines.filter(l=>db.items.find(i=>i.id===l.id)?.stock==null);if(unknown.length){toast('先に現在庫を棚卸してください：'+unknown.map(l=>l.name).join('、'));return}modal('入荷を記録',`<p>${esc(o.supplier)}からの発注分をすべて入荷済みにし、在庫へ加算します。</p><p>${o.lines.map(l=>`${esc(l.name)}：${l.qty} ${esc(l.unit)}`).join('<br>')}</p>`,()=>{if(o.status!=='発注済み')return false;for(const l of o.lines){const i=db.items.find(i=>i.id===l.id);i.stock=Math.round((i.stock+l.qty)*100)/100;log(i,'発注から入荷',l.qty,o.supplier)}o.status='入荷済み';toast('入荷を記録し、在庫を更新しました')})}
function download(name,body,type){const u=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function csv(head,rows,name){const cell=x=>'"'+String(typeof x==='string'&&/^[=+@\-\t\r]/.test(x)?"'"+x:x).replaceAll('"','""')+'"';download(name+'.csv','\uFEFF'+[head,...rows].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
$('#export').onclick=()=>csv(['商品','カテゴリー','現在庫','単位','適正数 / 発注点','単価','仕入先'],activeItems().map(i=>[i.name,i.category,i.stock??'',i.unit,i.min??'',i.price??'',i.supplier]),'在庫一覧');$('#backup').onclick=()=>download('kitchen-stock-backup.json',JSON.stringify(db,null,2),'application/json');$('#add').onclick=()=>page==='orders'?orderModal():itemModal();$('#close').onclick=$('#cancel').onclick=()=>$('#dialog').close();document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()});$('#today').textContent=new Date().toLocaleDateString('ja-JP',{year:'numeric',month:'long',day:'numeric',weekday:'short'});typeof initCloud==='function'?initCloud():render();
